  {
    "id": "p1-ipv4-intra",
    "priority": 300,
    "outputPorts": [2, 3],
    "match": {
      "inPort": 1,
      "etherType": 2048,
      "srcIp": "10.0.2.0",
      "srcIpPrefixLen": 24,
      "dstIp": "10.0.2.0",
      "dstIpPrefixLen": 24
    }
  },
  {
    "id": "p1-arp",
